/**
 * Opaque local completion references only. An empty object clears both fields; a channel requires a navigation target.
 */
export interface SurveyCompletionOperations {
  /**
   * @minLength 1
   * @maxLength 128
   * @pattern ^[A-Za-z0-9._:-]{1,128}$
   */
  navigation_target_id?: string;
  /** @minimum 0 */
  channel_id?: number;
}

/**
 * When enabled is true, configuration_reference is a required opaque local reference. When false, it is absent or empty. It is never a URL, token, payload, retry policy, or provider receipt.
 */
export interface SurveyExternalPushOperations {
  enabled: boolean;
  /**
   * @minLength 1
   * @maxLength 128
   * @pattern ^[A-Za-z0-9._:-]{1,128}$
   */
  configuration_reference?: string;
}

/**
 * PII-free local binding projection. Provider acceptance and delivery proof are independent facts.
 */
export interface SurveyExternalPushBindingDetail {
  /** @minimum 1 */
  submission_id: number;
  /**
   * @minLength 1
   * @maxLength 19
   * @pattern ^[1-9][0-9]{0,18}$
   */
  effect_id: string;
  state: ExternalEffectRuntimeState;
  provider_accepted: boolean;
  delivery_proven: boolean;
}

/**
 * Lease-fenced digest-only manual reconciliation. It cannot enqueue or retry an external dispatch.
 */
export interface SurveyExternalPushReconcileRequest {
  /**
   * @minLength 1
   * @maxLength 19
   * @pattern ^[1-9][0-9]{0,18}$
   */
  effect_id: string;
  /** @minimum 1 */
  generation: number;
  /** @minimum 1 */
  fence: number;
  lease_expires_at: string;
  /** @pattern ^sha256:[0-9a-f]{64}$ */
  evidence_digest: string;
  provider_accepted: boolean;
  delivery_proven: boolean;
}

export interface SurveyOperationsProjection {
  /** @minimum 1 */
  questionnaire_id: number;
  completion: SurveyCompletionOperations;
  external_push: SurveyExternalPushOperations;
  local_only: boolean;
}

